const $=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const statusLabels={AGUARDANDO_NFSE:'Aguardando NFS-e',NFSE_EM_ANALISE:'NFS-e em análise',NFSE_REJEITADA:'NFS-e rejeitada',AUTORIZADO:'Autorizado para pagamento',ENVIADO_AO_BANCO:'Enviado ao banco',PAGO:'Pago',FALHOU:'Falha no pagamento',CANCELADO:'Cancelado'};
const statusGuidance={AGUARDANDO_NFSE:'Aguardando o montador anexar a NFS-e pelo valor total deste borderô.',NFSE_EM_ANALISE:'A NFS-e foi recebida e aguarda conferência.',NFSE_REJEITADA:'A NFS-e foi rejeitada. O montador deverá enviar um novo documento.',AUTORIZADO:'Documento aprovado. Pagamento liberado para remessa bancária.',ENVIADO_AO_BANCO:'Remessa enviada. Aguardando retorno bancário.',PAGO:'Pagamento concluído e repasses dos atendimentos baixados.',FALHOU:'O banco informou falha. Revise a ocorrência antes de reenviar.',CANCELADO:'Este pagamento foi cancelado.'};
let payments=[],permissions={podeAutorizar:false,podeOperarCnab:false};
async function api(url,options={}){const response=await fetch(url,{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/admin/';throw new Error('Sessão expirada.')}if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');return data}
function showMessage(text,{success=false}={}){const box=$('#message');box.hidden=!text;box.className=success?'success':'';box.textContent=text||''}
function selected(){return[...document.querySelectorAll('.cnab-payment:checked')].map(input=>input.value)}
function updateSelection(){const ids=selected();$('#generate-cnab').disabled=!ids.length;$('#generate-cnab').textContent=ids.length?`Gerar remessa (${ids.length})`:'Gerar remessa dos selecionados'}
function actions(item){if(!permissions.podeAutorizar)return'';const review=item.status==='NFSE_EM_ANALISE'?`<div class="payment-actions"><button data-action="APROVAR_NFSE" data-id="${item.id}">Aprovar NFS-e</button><button class="secondary" data-action="REJEITAR_NFSE" data-id="${item.id}">Rejeitar NFS-e</button></div>`:'';const manual=['AUTORIZADO','ENVIADO_AO_BANCO','FALHOU'].includes(item.status)?`<div class="payment-actions"><button class="secondary" data-action="BAIXAR_MANUAL" data-id="${item.id}">Registrar pagamento manual</button></div>`:'';return review+manual}
function itemsTable(items){return`<details class="payment-items" ${items.length<=3?'open':''}><summary>${items.length} atendimento${items.length===1?'':'s'} neste borderô — ${money(items.reduce((sum,item)=>sum+Number(item.valor||0),0))}</summary><table class="items-table"><thead><tr><th>Atendimento</th><th>Serviço</th><th>Repasse</th></tr></thead><tbody>${items.map(item=>`<tr><td><strong>#${escapeHtml(item.numero_atendimento)}</strong><small>${escapeHtml(item.nome_cliente||'Cliente não informado')}</small></td><td>${escapeHtml(item.descricao_servico||'Serviço não informado')}<small>Concluído em ${date(item.concluido_montador_em)}</small></td><td><strong>${money(item.valor)}</strong></td></tr>`).join('')}</tbody></table></details>`}
function paymentCard(item){const items=Array.isArray(item.itens)?item.itens:[],nfse=item.nfse_nome?`<strong>NFS-e anexada</strong><span>${escapeHtml(item.nfse_nome)} · ${escapeHtml(item.nfse_status||'Aguardando análise')}</span><a class="nfse-link" href="/api/admin/montador-documento?id=${item.nfse_documento_id}" target="_blank" rel="noopener">Visualizar documento</a>`:`<strong>NFS-e pendente</strong><span>${escapeHtml(statusGuidance[item.status]||'Documento ainda não anexado.')}</span>`;return`<article class="payment"><div class="payment-head"><div class="payment-reference"><small>Borderô #${escapeHtml(item.numero||'—')} · ${escapeHtml(item.documento_bancario||'Documento não informado')}</small><strong>${escapeHtml(item.montador_nome||'Montador não informado')}</strong></div><div class="payment-amount"><span>Valor total previsto</span><strong>${money(item.valor_total)}</strong></div><span class="status status-${String(item.status).toLowerCase()}">${escapeHtml(statusLabels[item.status]||item.status)}</span></div><div class="payment-body"><div class="payment-meta"><div><span>Gerado em</span><strong>${date(item.criado_em)}</strong></div><div><span>Atendimentos</span><strong>${items.length}</strong></div><div><span>Situação</span><strong>${escapeHtml(statusGuidance[item.status]||statusLabels[item.status]||item.status)}</strong></div></div><aside class="nfse-box">${nfse}${actions(item)}</aside></div>${permissions.podeOperarCnab&&item.status==='AUTORIZADO'?`<label class="payment-select"><input class="cnab-payment" type="checkbox" value="${item.id}"> Incluir este pagamento na próxima remessa CNAB</label>`:''}${itemsTable(items)}</article>`}
function renderSummary(){const counts=payments.reduce((all,item)=>(all[item.status]=(all[item.status]||0)+1,all),{}),cards=[['AGUARDANDO_NFSE','Aguardando NFS-e','Documento pendente'],['NFSE_EM_ANALISE','NFS-e em análise','Requer conferência'],['AUTORIZADO','Autorizados','Prontos para pagamento'],['PAGO','Pagos','Concluídos']];$('#summary').innerHTML=cards.map(([status,title,caption])=>`<article><span>${title}</span><strong>${counts[status]||0}</strong><small>${caption}</small></article>`).join('')}
function renderPayments(){const status=$('#payment-status-filter').value,rows=payments.filter(item=>!status||item.status===status);$('#payments').innerHTML=rows.length?rows.map(paymentCard).join(''):'<div class="empty-payment">Nenhum pagamento encontrado nesta situação.</div>';updateSelection()}
async function loadCnab(){if(!permissions.podeOperarCnab)return;try{const cnab=await api('/api/admin/montador-cnab');if(cnab.configuracao){for(const [key,value] of Object.entries(cnab.configuracao)){const field=$('#cnab-form').elements[key.replace(/_([a-z])/g,(_,letter)=>letter.toUpperCase())];if(field)field.type==='checkbox'?field.checked=Boolean(value):field.value=value??''}}}catch(error){showMessage(error.message)}}
async function load(){showMessage('');try{const data=await api('/api/admin/montador-pagamentos');payments=data.pagamentos||[];permissions=data.permissoes||permissions;$('#cnab-area').hidden=!permissions.podeOperarCnab;renderSummary();renderPayments();await loadCnab()}catch(error){showMessage(error.message);$('#payments').innerHTML='<div class="empty-payment">Não foi possível carregar os pagamentos.</div>'}}
$('#payment-status-filter').addEventListener('change',renderPayments);
$('#payments').addEventListener('change',event=>{if(event.target.matches('.cnab-payment'))updateSelection()});
$('#payments').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;let justificativa;if(button.dataset.action==='BAIXAR_MANUAL'){justificativa=prompt('Informe a justificativa da baixa manual:');if(!justificativa)return}button.disabled=true;try{const data=await api('/api/admin/montador-pagamentos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:button.dataset.action,id:button.dataset.id,justificativa})});showMessage(data.mensagem,{success:true});await load()}catch(error){showMessage(error.message);button.disabled=false}});
$('#cnab-form').addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));values.acao='CONFIGURAR';values.ativo=event.currentTarget.elements.ativo.checked;try{const data=await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});showMessage(data.mensagem,{success:true})}catch(error){showMessage(error.message)}});
$('#generate-cnab').addEventListener('click',async()=>{try{await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'GERAR_REMESSA',pagamentoIds:selected()})})}catch(error){showMessage(error.message)}});
$('#cnab-return').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'IMPORTAR_RETORNO',nomeArquivo:file.name,conteudo:await file.text()})})}catch(error){showMessage(error.message)}finally{event.target.value=''}});
$('#refresh').addEventListener('click',load);load();
